entries[435472] = { ["name"] = "Temporale Verzerrung", ["text"] = "Sofort\nVerlasst in regelmäßigen Abständen den regulären Fluss der Zeit.\n(Procchance: 30%, 1s Abklingzeit)" }
entries[435473] = { ["name"] = "Ewig brennende Laterne", ["text"] = "Ca. 30 Procs pro Minute\nEure schädlichen Distanzkampfzauber und -fähigkeiten haben eine hohe Chance, die Flamme der Laterne zu schüren. Gewährt bis zu 15-mal einen Stapel 'Lampenlicht'.\n\nNach 30 Sek. werden die gesammelten Stapel von 'Lampenlicht' verbraucht, um eine entsprechende Anzahl an Glühwürmchen anzuziehen. Die Glühwürmchen stürzen sich auf das nächste Ziel, das Ihr angreift, explodieren und verursachen pro Glühwürmchen ( 1 * 82 ) Feuerschaden." }
entries[435474] = { ["name"] = "Vorspulen", ["text"] = "Sofort\nIncreases the caster's attacking and casting speed by 30% for 5 Sek..\nIncreases the movement speed of the caster by 50% for 5 Sek.." }
entries[435475] = { ["name"] = "Abgrundfalle", ["text"] = "Sofort 1 min Abklingzeit\nPlatziert eine Abgrundfalle zu Euren Füßen. Wenn sich ein Gegner bis auf 3 Meter nähert, wird für 10 Sek. eine riesige Wasserblase erzeugt. Alle Gegner innerhalb der Blase erleiden pro Sekunde ( 1 * 105 ) Frostschaden.\n\nDie Falle bleibt 1 Min. lang bestehen, bevor sie automatisch entschärft wird." }
entries[435476] = { ["name"] = "Temporale Verzerrung", ["text"] = "Sofort\nIhr fühlt Euch von dieser Zeitlinie getrennt." }
entries[435478] = { ["name"] = "Explosives Artefakt", ["text"] = "Sofort\n[NYI - Needs trigger] Explode flames outwards in front of you, inflicting 8 Fire damage to any enemy caught in the effect." }
entries[435479] = { ["name"] = "Flöte des Fungusfreunds", ["text"] = "Ca. 1 Procs pro Minute\nZauber und Fähigkeiten haben eine Chance, dass sich ein farbenprächtiger Fungusfreund aus der Erde emporgräbt, der Verbündete um 2437 Gesundheit heilt, Euch 237 Mana gewährt oder einem Gegner in der Nähe im Verlauf von 3 Sek. ( 555 * 3) Naturschaden zufügt.\n(1s Abklingzeit)" }
entries[435482] = { ["name"] = "Seidenkettenweber", ["text"] = "Sofort 1 min Abklingzeit" }
entries[435485] = { ["name"] = "Eisenluntenbombe", ["text"] = "Sofort\nIhr habt eine Bombe! Schnell, werdet sie wieder los!" }
entries[435486] = { ["name"] = "Königsmord", ["text"] = "Unbegrenzte Reichweite\nSofort\nNetherphantome stürzen sich durch die Schatten auf anvisierte Spielercharaktere und fügen Spielercharakteren auf ihrem Weg 4029421 Schattenschaden zu." }
entries[435487] = { ["name"] = "Serum der zügellosen Kampfeslust", ["text"] = "Sofort 1 min Abklingzeit\nDie Einnahme des Serums steigert Eure Sinne 3 Sek. lang bis an ihre Grenzen, sodass Ihr 100% Schadensverringerung erhaltet, bis zu einem Maximum von X Schaden.\nWenn durch diesen Effekt Schaden verringert wird, schlagt Ihr mit einem 'Konter' zurück, der Eurem Angreifer Y körperlichen Schaden zufügt.\n\nWenn Ihr während der ersten 1,5 Sek. der Effektdauer einen 'Konter' ausführt, wird stattdessen ein 'Perfekter Konter' ausgeführt, der 100% mehr Schaden verursacht.\n\nEs kann pro Einsatz nur ein 'Konter' oder 'Perfekter Konter' ausgeführt werden." }
entries[435488] = { ["name"] = "Bemerkenswerter Blasphemit", ["text"] = "Sofort\nErhöht das maximale Mana um 1% pro einzigartiger Farbe aktuell gesockelter Khaz-Algar-Edelsteine." }
entries[435490] = { ["name"] = "Hubertas Pfeife" }
entries[435493] = { ["name"] = "Mixtur: Kuss des Todes", ["text"] = "Sofort 2.5 min Abklingzeit\nTrinkt aus der Phiole, damit die Toxine durch Eure Adern zirkulieren und alle Sekundärwerte 30 Sek. lang um 63 erhöhen.\n\nSpringt, um Euch das Gegengift zu verabreichen und den Effekt zu beenden.\n\nWenn Ihr das Gegengift nicht vor Ablauf des Effekts einnehmt, werdet Ihr für 5 Sek. betäubt." }
entries[435494] = { ["name"] = "Hals- und Beinbruch!", ["text"] = "15 Meter Reichweite\nSofort 1.5 sek. Abklingzeit\nFeuert ein anderes Mitglied der Truppe an!" }
entries[435496] = { ["name"] = "Phiolengurt", ["text"] = "Sofort 1 min Abklingzeit\nTrinkt eine Phiole aus dem Gürtel." }
entries[435499] = { ["name"] = "Eisenluntenbombe", ["text"] = "35 Meter Reichweite\nSofort\nZerstört Türme und fügt Gegnern innerhalb von 8 Metern um den Einschlag zusätzlich 7 Feuerschaden zu.\n\nWerft sie schnell, bevor sie explodiert!" }
entries[435500] = { ["name"] = "Gipfelblasphemit", ["text"] = "Sofort\nErhöht den Effekt von kritischen Treffern um 0.1% pro einzigartiger Farbe aktuell gesockelter Edelsteine von Khaz Algar." }
entries[435501] = { ["name"] = "Flüchtiger Blasphemit", ["text"] = "Sofort\nErhöht den Effekt von kritischen Treffern um 2% pro einzigartiger Farbe aktuell gesockelter Khaz-Algar-Edelsteine." }
entries[435502] = { ["name"] = "Schattenbindendes Ritualmesser", ["text"] = "Ca. 0.5 Procs pro Minute\nGraviert ein Ritualsiegel in Eure Haut, das Euch an die Schatten bindet und 43 Hauptwert gewährt.\n\nEure Zauber und Fähigkeiten haben eine geringe Chance, einen Eurer Sekundärwerte im Kampf 10 Sek. lang um 158 zu verringern." }
