entries[435791] = { ["name"] = "Blitzschlag", ["text"] = "40 Meter Reichweite\nSofort\nSchutz\nWenn Ihr Gegnern mit 'Donnerknall', 'Rache', oder 'Hinrichten' Schaden zufügt, besteht eine Chance von 25%, dass einer zusätzlich von einem Blitzschlag getroffen wird, der (103.4% der Angriffskraft) Naturschaden verursacht .\n\nBlitzschläge treten 30% häufiger auf, während 'Avatar' aktiv ist.\n\nFuror\nWenn Ihr Gegnern mit 'Donnerknall', 'Wütender Schlag' oder 'Hinrichten' Schaden zufügt, besteht eine Chance von 25%, dass einer zusätzlich von einem Blitzschlag getroffen wird, der (103.4% der Angriffskraft) Naturschaden verursacht .\n\nBlitzschläge treten 30% häufiger auf, während 'Avatar' aktiv ist." }
