entries[435793] = { ["name"] = "Klebrige Eruption", ["text"] = "100 Meter Reichweite\nSofort\nRasha'nan stößt wild Spinnweben aus, während sich keine Spielercharaktere in Nahkampfreichweite befinden, und verursacht 6061123 Naturschaden sowie 9 Sek. lang alle 3 Sek. 2424449 zusätzlichen Naturschaden. Dieser Effekt ist stapelbar." }
