entries[435811] = { ["name"] = "Mykopracht", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nMykopracht ist ein sehr weit verbreiteter Pilz, der auf Khaz Algar zu finden ist. Es kann auf praktisch jedem Terrain gefunden werden, da der Pilz absolut überall wächst." }
entries[435812] = { ["name"] = "Üppige Mykopracht", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nMykopracht ist ein sehr weit verbreiteter Pilz, der auf Khaz Algar zu finden ist. Es kann auf praktisch jedem Terrain gefunden werden, da der Pilz absolut überall wächst.\n\nManche Kräuter wachsen besonders gut und gedeihen aus allerlei Gründen, ganz unabhängig vom Klima oder Ort. Kräuterkundige, die auf diese seltenen Kräuter stoßen, können zusätzliche nützliche Materialien ergattern.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
entries[435813] = { ["name"] = "Instabile Energie", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Instabile Fragmente aufgehoben werden, werden Heilung und Schaden gegen ' Verstärkter Panzer ' 30 Sek. lang um 50% erhöht. Dieser Effekt ist stapelbar.\n\nZusätzlich fügt ' Instabile Energie ' allen betroffenen Spielercharakteren alle 2 Sek. 363667 Schattenschaden zu." }
