entries[435821] = { ["name"] = "Reiztropfen", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEine fleischfressende Pflanze, die in den unterirdischen Bereichen von Khaz Algar gefunden werden kann. Reiztropfen setzen kleine biolumineszente Lichter ein, um Insekten und andere Beute anzulocken, von denen sie sich ernähren.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
entries[435822] = { ["name"] = "Orbinid", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nKhaz Algar beherbergt viele einzigartige Pflanzenarten, und das Orbinid ist ein Teil von diesen. Die Pflanze scheint latente Magie in einer zähflüssigen Kugel zu absorbieren, die von verschiedenen Berufen eingesetzt werden kann, um Dinge wie Salben und Tinten herzustellen.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
entries[435823] = { ["name"] = "Segensblume", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nDie Segensblume von Khaz Algar sieht auf den ersten Blick harmlos aus, aber Vorsicht: Sie enthält ein gefährliches Gift, das äußerst krank macht.\n\nFachgerecht vorbereitet haben Segensblumen aber verschiedene Anwendungen in der Medizin, und in ihre Kappen gefüllter Tee gilt als Delikatesse.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
