entries[435826] = { ["name"] = "Arathors Speer", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nArathors Speer ist ein in den hellen Außengebieten von Khaz Algar zu findendes, herzhaftes Kraut mit vielen Einsatzmöglichkeiten.\n\nBesonders bemerkenswert sind die Fasern, die zu Pergament gewebt oder eng geschichtet und behandelt werden können, um ein holzähnliches Material herzustellen.\n\nDies ermöglicht es, von Büchern über Bögen bis hin zu Stäben alles herzustellen.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
entries[435829] = { ["name"] = "Üppiger Reiztropfen", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEine fleischfressende Pflanze, die in den unterirdischen Bereichen von Khaz Algar gefunden werden kann. Reiztropfen setzen kleine biolumineszente Lichter ein, um Insekten und andere Beute anzulocken, von denen sie sich ernähren.\n\nManche Kräuter wachsen besonders gut und gedeihen aus allerlei Gründen, ganz unabhängig vom Klima oder Ort. Kräuterkundige, die auf diese seltenen Kräuter stoßen, können zusätzliche nützliche Materialien ergattern.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
entries[435830] = { ["name"] = "Üppiges Orbinid", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nKhaz Algar beherbergt viele einzigartige Pflanzenarten, und das Orbinid ist ein Teil von diesen. Die Pflanze scheint latente Magie in einer zähflüssigen Kugel zu absorbieren, die von verschiedenen Berufen eingesetzt werden kann, um Dinge wie Salben und Tinten herzustellen.\n\nManche Kräuter wachsen besonders gut und gedeihen aus allerlei Gründen, ganz unabhängig vom Klima oder Ort. Kräuterkundige, die auf diese seltenen Kräuter stoßen, können zusätzliche nützliche Materialien ergattern.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
entries[435834] = { ["name"] = "Üppige Segensblume", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nDie Segensblume von Khaz Algar sieht auf den ersten Blick harmlos aus, aber Vorsicht: Sie enthält ein gefährliches Gift, das äußerst krank macht.\n\nFachgerecht vorbereitet haben Segensblumen aber verschiedene Anwendungen in der Medizin, und in ihre Kappen gefüllter Tee gilt als Delikatesse.\n\nManche Kräuter wachsen besonders gut und gedeihen aus allerlei Gründen, ganz unabhängig vom Klima oder Ort. Kräuterkundige, die auf diese seltenen Kräuter stoßen, können zusätzliche nützliche Materialien ergattern.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
entries[435836] = { ["name"] = "Üppiger Arathors Speer", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nArathors Speer ist ein in den hellen Außengebieten von Khaz Algar zu findendes, herzhaftes Kraut mit vielen Einsatzmöglichkeiten.\n\nBesonders bemerkenswert sind die Fasern, die zu Pergament gewebt oder eng geschichtet und behandelt werden können, um ein holzähnliches Material herzustellen.\n\nDies ermöglicht es, von Büchern über Bögen bis hin zu Stäben alles herzustellen.\n\nManche Kräuter wachsen besonders gut und gedeihen aus allerlei Gründen, ganz unabhängig vom Klima oder Ort. Kräuterkundige, die auf diese seltenen Kräuter stoßen, können zusätzliche nützliche Materialien ergattern.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
entries[435838] = { ["name"] = "Kristallisierte Mykopracht", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nMykopracht ist ein sehr weit verbreiteter Pilz, der auf Khaz Algar zu finden ist. Es kann auf praktisch jedem Terrain gefunden werden, da der Pilz absolut überall wächst.\n\nAufgrund ihrer Nähe zum Kernweg haben einige Kräuter eine innigere Verbindung zur Weltenseele. Diese Verbindung hat dazu geführt, dass einige Kräuter teilweise kristallisiert sind. Jeder Kräuterkundige, der eines dieser Kräuter sammelt, erhält einen kleinen Segen sowie etwas kristallines Pulver.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
entries[435840] = { ["name"] = "Modifizierte Mykopracht", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nMykopracht ist ein sehr weit verbreiteter Pilz, der auf Khaz Algar zu finden ist. Es kann auf praktisch jedem Terrain gefunden werden, da der Pilz absolut überall wächst.\n\nTief unter der Oberfläche von Khaz Algar liegt das schwarze Blut der Alten Götter. Dieses hat begonnen, sich anzusammeln und durch sein Schwären die örtliche Flora zu verändern. Kräuter, die das Pech hatten, in der Nähe dieses Einflusses zu wachsen, haben sich verändert... sind gefährlich geworden. Jeder Kräuterkundige, der sich den Tiefen stellt und derartige Kräuter sammelt, muss sich zwar der Gefahr durch die Pflanze selbst stellen, erhält dafür aber auch zappelnde Proben.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
entries[435843] = { ["name"] = "Verstrahlte Mykopracht", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nMykopracht ist ein sehr weit verbreiteter Pilz, der auf Khaz Algar zu finden ist. Es kann auf praktisch jedem Terrain gefunden werden, da der Pilz absolut überall wächst.\n\nJüngste Ereignisse haben dazu geführt, dass große Mengen arkaner Magie in den Boden von Khaz Algar gesickert sind. Wie schon auf den Dracheninseln festgestellt, neigt die Flora dazu, für magische Einflüsse anfällig zu sein, und die Situation hier ist nicht anders.\n\nManche Kräuter hier wurden durch arkane Energie verstrahlt, was dem Kräuterkundigen beim Sammeln einige Leylinienrückstände einbringt. Was mit der zurückbleibenden instabilen arkanen Energie geschieht, ist allerdings eine andere Geschichte...\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
