entries[435854] = { ["name"] = "Vergessenssphäre", ["text"] = "Formt eine Kugel aus reinster Leere, die den von Gegnern innerhalb von 15 Metern erlittenen Schaden 10 Sek. lang um 15% erhöht. Nach 4 Sek. explodiert die Kugel, verursacht 12438 Schattenschaden und betäubt getroffene Gegner für 1 Sek." }
