entries[435874] = { ["name"] = "Vergessenssphäre", ["text"] = "Unbegrenzte Reichweite\nSofort\nFormt eine Kugel aus reinster Leere, die den von Gegnern innerhalb von 15 Metern erlittenen Schaden 10 Sek. lang um 15% erhöht. Nach 4 Sek. explodiert die Kugel, verursacht Schattenschaden und betäubt getroffene Gegner für 1 Sek." }
