entries[436341] = { ["name"] = "Mineralien verspeisen", ["text"] = "Ihr seid immer satt auf erhöhter Effektivitätsstufe, könnt aber keine Nahrung zu Euch nehmen. Beim Verzehren eines Edelsteins von Khaz Algar wird der durch 'Satt' gewährte Bonus gewechselt.\n\nBernstein: Ausdauer\nSmaragd: Tempo\nOnyx: Meisterschaft\nRubin: Kritischer Trefferwert\nSaphir: Vielseitigkeit" }
