entries[436458] = { ["name"] = "Sprinten", ["text"] = "Erlernt folgenden Zauber.\n\nSprinten\nErhöht Eure Bewegungsgeschwindigkeit 8 Sek. lang um 70%." }
entries[436459] = { ["name"] = "Schneide des Arkanisten", ["text"] = "Eure Angriffe verbrauchen einen Teil Eures Absorptionsschilds, um Arkanschaden in Höhe der verbrauchten Menge zu verursachen. (10 Sek. Abklingzeit)" }
entries[436460] = { ["name"] = "Eifer", ["text"] = "Während Ihr mehr als 80% Gesundheit besitzt, verbrauchen Eure Angriffe Gesundheit und verursachen Heiligschaden in Höhe der verbrauchten Menge. (1 Sek. Abklingzeit)" }
entries[436461] = { ["name"] = "Mal der Arroganz", ["text"] = "Angreifer erhalten ein 'Mal der Arroganz', das 10 Sek. lang alle 2 Sek. Schattenschaden verursacht und bis zu 5-mal stapelbar ist." }
entries[436462] = { ["name"] = "Opportunist", ["text"] = "Gewährt 4 Sek. lang, nachdem Ihr einen Gegner betäubt habt, eine um 50% erhöhte kritische Trefferchance." }
entries[436463] = { ["name"] = "Rasanter Schlag", ["text"] = "Eure Nahkampfangriffe haben eine Chance von 100%, 4 bis 7 zusätzliche automatische Angriffe auszulösen. (10 Sek. Abklingzeit)" }
entries[436464] = { ["name"] = "Töten", ["text"] = "Wenn Ihr einen Gegner angreift, der weniger als 10% Gesundheit besitzt, versucht Ihr, ihn zu 'Töten', was Schattenschaden in Höhe von 100% Eurer maximalen Gesundheit verursacht.\n\nIhr könnt höchstens einmal versuchen, einen Gegner zu 'Töten'." }
entries[436465] = { ["name"] = "Erblühen des Sonnenwanderers", ["text"] = "Eure kritischen Treffer brechen in einer feurigen Explosion aus, die Gegnern innerhalb von 15 Metern um Euer Ziel Feuerschaden zufügt." }
entries[436466] = { ["name"] = "Schild des Tüftlermeisters", ["text"] = "Gewährt einen Schild, der Schaden in Höhe von 15% Eurer Gesamtgesundheit verursacht.\n\nDieser Schild regeneriert sich, wenn er 5 Sek. lang keinen Schaden erleidet." }
entries[436467] = { ["name"] = "Siegesfeuer", ["text"] = "Immer, wenn Ihr einen Gegner besiegt, brecht Ihr aus, was innerhalb von 12 Metern Gegnern Feuerschaden zufügt und Verbündete heilt." }
