entries[436700] = { ["name"] = "Boshafte Juweliersfassung", ["text"] = "Sofort\nFügt einem PvP-Gegenstand von The War Within 1 [Sockel][Sockel] hinzu. Kann auf Helme, Amulette, Armschienen, Gürtel und Ringe angewendet werden.\n[\nSchmuck kann bis zu 2 Sockel haben.]\nMuss innerhalb von Saison 3 von The War Within verwendet werden." }
