entries[436707] = { ["name"] = "Grollender Donner", ["text"] = "Furor\nErhöht von Euren Fähigkeiten verursachten Sturmschlag- oder Naturschaden um 5%. Sturmschlagschaden ignoriert Rüstung.\n\n'Donnerknall' verursacht 40% mehr Schaden und erzeugt 8 Wut.\n\n'Seismischer Nachhall', 'Verbesserter Wirbelwind', 'Metzger' und 'Barbarentraining' verbessern zusätzlich zu 'Wirbelwind' auch 'Donnerknall'.\n\nSchutz\nErhöht von Euren Fähigkeiten verursachten Sturmschlag- oder Naturschaden um 5%. Sturmschlagschaden ignoriert Rüstung.\n\n'Donnerknall' verursacht 40% mehr Schaden.\n\n'Seismischer Nachhall' verbessert zusätzlich zu 'Wirbelwind' auch 'Donnerknall'." }
